from decimal import Decimal


def _numeric_line_no(value: object) -> Decimal:
    """Return the legacy numeric comparison value for LINE_NO."""
    if isinstance(value, str) and value.strip() == "":
        return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted order lines and assign contiguous line numbers per order."""
    orders: dict[str, list[tuple[Decimal, int, dict]]] = {}

    for position, row in enumerate(lines):
        if row.get("DEL_FLG", "") == "Y":
            continue

        order_id = str(row.get("ORD_ID", ""))
        original_line_no = _numeric_line_no(row.get("LINE_NO", ""))
        orders.setdefault(order_id, []).append((original_line_no, position, row))

    result: list[dict] = []
    for order_id in sorted(orders):
        surviving_lines = sorted(orders[order_id], key=lambda item: (item[0], item[1]))
        for new_line_no, (_, _, row) in enumerate(surviving_lines, start=1):
            renumbered_row = dict(row)
            renumbered_row["LINE_NO"] = new_line_no
            result.append(renumbered_row)

    return result
